class Vehicle {
  #wheels;
  constructor(brand, wheels) {
    this.brand = brand;
    this.#wheels = wheels;
  }
  describe() {
    return `${this.brand} has ${this.#wheels} wheels`;
  }
}

class Car extends Vehicle {
  constructor(brand, doors) {
    super(brand, 4);
    this.doors = doors;
  }
  describe() {
    return `${super.describe()} and ${this.doors} doors`;
  }
}

const car = new Car('Toyota', 4);
console.log(car.describe());
console.log(car instanceof Vehicle);
console.log(Object.getPrototypeOf(car) === Car.prototype);
